package com.hotelmanagement.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="BOOKINGS") public class Booking {
 @Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="bookings_seq_gen") @SequenceGenerator(name="bookings_seq_gen",sequenceName="BOOKINGS_SEQ",allocationSize=1) @Column(name="ID") private Long id;
 @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="USER_ID",nullable=false) private User user; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="ROOM_ID",nullable=false) private Room room;
 @Column(name="CHECK_IN_DATE",nullable=false) private LocalDate checkInDate; @Column(name="CHECK_OUT_DATE",nullable=false) private LocalDate checkOutDate; @Column(name="TOTAL_PRICE") private BigDecimal totalPrice; @Column(name="BOOKING_STATUS") private String bookingStatus; @Column(name="CONFIRMATION_CODE",unique=true) private String confirmationCode; @Column(name="CREATED_AT") private LocalDateTime createdAt;
 public Booking(){} public Long getId(){return id;} public void setId(Long v){id=v;} public User getUser(){return user;} public void setUser(User v){user=v;} public Room getRoom(){return room;} public void setRoom(Room v){room=v;} public LocalDate getCheckInDate(){return checkInDate;} public void setCheckInDate(LocalDate v){checkInDate=v;} public LocalDate getCheckOutDate(){return checkOutDate;} public void setCheckOutDate(LocalDate v){checkOutDate=v;} public BigDecimal getTotalPrice(){return totalPrice;} public void setTotalPrice(BigDecimal v){totalPrice=v;} public String getBookingStatus(){return bookingStatus;} public void setBookingStatus(String v){bookingStatus=v;} public String getConfirmationCode(){return confirmationCode;} public void setConfirmationCode(String v){confirmationCode=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}
}